{"edits":[{"old":"    // Manual mode: clear any retained automatic sequence state.
    tmp_MoveToB := FALSE;
    tmp_MoveToC := FALSE;
    tmp_Completed := FALSE;
","new":"    // Manual mode: movement automatic sequence state is cleared,
