    tmp_MoveToB := FALSE;
    tmp_MoveToC := FALSE;
"},{"old":"CompletionLight := Mode AND tmp_Completed;","new":"CompletionLight := tmp_Completed;"},{"old":"  - Retained latches survive mode switches; arrival resets occur even in manual.
