edits.old:
// Manual mode: clear any retained automatic sequence state.
tmp_MoveToB := FALSE;
tmp_MoveToC := FALSE;
tmp_Completed := FALSE;

edits.new:
// Manual mode: movement automatic sequence state is cleared,
// but the completion latch is retained so CompletionLight can
// remain on until SensorC releases the product.
tmp_MoveToB := FALSE;
tmp_MoveToC := FALSE;
